/* Julia at 24: interactive memory map.
 * Data comes from assets/data.js (generated by scripts/build_data.py).
 */
(() => {
  "use strict";

  const DATA = window.MEMMAP;
  const PLACES = DATA.places;
  const PEOPLE_COUNT = PLACES.reduce((n, p) => n + p.people.length, 0);
  const REGION_LABEL = { nyc: "New York City", northeast: "Close to home", world: "Around the world" };

  // Places pinned at town/region level get a wider camera.
  const ZOOM = { chengdu: 10.6, hamptons: 10.2, oley: 12.6, beacon: 13, vancouver: 11.6, usj: 14.8 };
  const WORLD_VIEW = { center: [-25, 32], zoom: 1.45, pitch: 0, bearing: 0 };
  const CLUSTER_PX = 56;

  const GLYPHS = "https://tiles.openfreemap.org/fonts/{fontstack}/{range}.pbf";
  const SKY = {
    "sky-color": "#7FB2DA",
    "horizon-color": "#DCEBF5",
    "fog-color": "#EAF2F8",
    "sky-horizon-blend": 0.5,
    "horizon-fog-blend": 0.6,
    "fog-ground-blend": 0.7,
    "atmosphere-blend": ["interpolate", ["linear"], ["zoom"], 0, 1, 5, 1, 8, 0],
  };

  const $ = (sel, root = document) => root.querySelector(sel);
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const canHover = window.matchMedia("(hover: hover)").matches;
  const isNarrow = () => window.innerWidth <= 720;

  const store = {
    get(k) { try { return localStorage.getItem(k); } catch { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch { /* private mode */ } },
  };

  const state = {
    mode: store.get("memmap-mode") === "map" ? "map" : "earth",
    current: -1,
    tour: false,
    dirOpen: false,
    spinning: false,
  };

  // ------------------------------------------------------------------
  // Map styles
  // ------------------------------------------------------------------
  function earthStyle() {
    const esri = (path) => [`https://server.arcgisonline.com/ArcGIS/rest/services/${path}/MapServer/tile/{z}/{y}/{x}`];
    return {
      version: 8,
      glyphs: GLYPHS,
      projection: { type: "globe" },
      sky: SKY,
      sources: {
        sat: { type: "raster", tiles: esri("World_Imagery"), tileSize: 256, maxzoom: 19,
               attribution: "Imagery © Esri, Maxar, Earthstar Geographics" },
        roads: { type: "raster", tiles: esri("Reference/World_Transportation"), tileSize: 256, maxzoom: 19 },
        labels: { type: "raster", tiles: esri("Reference/World_Boundaries_and_Places"), tileSize: 256, maxzoom: 19 },
      },
      layers: [
        { id: "bg", type: "background", paint: { "background-color": "#0B1426" } },
        { id: "sat", type: "raster", source: "sat", paint: { "raster-saturation": 0.12, "raster-contrast": 0.05 } },
        { id: "roads", type: "raster", source: "roads", minzoom: 12, paint: { "raster-opacity": 0.5 } },
        { id: "labels", type: "raster", source: "labels", paint: { "raster-opacity": 0.92 } },
      ],
    };
  }

  let libertyCache = null;
  async function mapStyle() {
    if (!libertyCache) {
      libertyCache = await (await fetch("https://tiles.openfreemap.org/styles/liberty")).json();
    }
    const s = JSON.parse(JSON.stringify(libertyCache));
    s.projection = { type: "globe" };
    s.sky = SKY;
    const paint = {
      background: { "background-color": "#F3EAD7" },
      water: { "fill-color": "#A9CFE3" },
      park: { "fill-color": "#C6DDAE", "fill-opacity": 0.9 },
      landcover_grass: { "fill-color": "#D3E3BC" },
      landcover_wood: { "fill-color": "#BCD6A3" },
      landuse_residential: { "fill-color": "#EFE4CF" },
      building: { "fill-color": "#E6D9BF" },
      "building-3d": { "fill-extrusion-color": "#EADFCB", "fill-extrusion-opacity": 0.85 },
    };
    s.layers = s.layers.filter((l) => !["poi_r20", "poi_r7", "poi_transit"].includes(l.id));
    for (const l of s.layers) {
      if (paint[l.id]) l.paint = Object.assign(l.paint || {}, paint[l.id]);
    }
    return s;
  }

  async function styleFor(mode) {
    if (mode === "map") {
      try { return await mapStyle(); } catch (e) { console.warn("Map style unavailable, using Earth", e); }
    }
    return earthStyle();
  }

  // ------------------------------------------------------------------
  // Journey route (great-circle legs, split at the antimeridian)
  // ------------------------------------------------------------------
  function gcPoints(a, b) {
    const R = Math.PI / 180;
    const [l1, p1, l2, p2] = [a[0] * R, a[1] * R, b[0] * R, b[1] * R];
    const d = 2 * Math.asin(Math.sqrt(Math.sin((p2 - p1) / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin((l2 - l1) / 2) ** 2));
    if (d < 0.02) return [a, b];
    const n = Math.max(8, Math.ceil(d / R / 1.5));
    const pts = [];
    for (let k = 0; k <= n; k++) {
      const f = k / n;
      const A = Math.sin((1 - f) * d) / Math.sin(d);
      const B = Math.sin(f * d) / Math.sin(d);
      const x = A * Math.cos(p1) * Math.cos(l1) + B * Math.cos(p2) * Math.cos(l2);
      const y = A * Math.cos(p1) * Math.sin(l1) + B * Math.cos(p2) * Math.sin(l2);
      const z = A * Math.sin(p1) + B * Math.sin(p2);
      pts.push([Math.atan2(y, x) / R, Math.atan2(z, Math.hypot(x, y)) / R]);
    }
    return pts;
  }

  function routeGeoJSON() {
    const lines = [[]];
    for (let i = 0; i < PLACES.length - 1; i++) {
      const pts = gcPoints([PLACES[i].lng, PLACES[i].lat], [PLACES[i + 1].lng, PLACES[i + 1].lat]);
      for (const p of pts) {
        const cur = lines[lines.length - 1];
        const prev = cur[cur.length - 1];
        if (prev && Math.abs(p[0] - prev[0]) > 180) {
          const edge = prev[0] > 0 ? 180 : -180;
          const span = 360 - Math.abs(p[0] - prev[0]);
          const f = (edge - prev[0]) / (prev[0] > 0 ? span : -span);
          const lat = prev[1] + (p[1] - prev[1]) * f;
          cur.push([edge, lat]);
          lines.push([[-edge, lat]]);
        }
        lines[lines.length - 1].push(p);
      }
    }
    return { type: "Feature", geometry: { type: "MultiLineString", coordinates: lines }, properties: {} };
  }
  const ROUTE = routeGeoJSON();

  function addRoute() {
    if (map.getSource("route")) return;
    map.addSource("route", { type: "geojson", data: ROUTE });
    map.addLayer({
      id: "route-halo", type: "line", source: "route",
      layout: { "line-cap": "round", "line-join": "round" },
      paint: { "line-color": "#FBF5EA", "line-width": ["interpolate", ["linear"], ["zoom"], 1, 3.5, 14, 7], "line-opacity": 0.55, "line-blur": 1.5 },
    });
    map.addLayer({
      id: "route", type: "line", source: "route",
      layout: { "line-cap": "round", "line-join": "round" },
      paint: {
        "line-color": "#E4572E",
        "line-width": ["interpolate", ["linear"], ["zoom"], 1, 1.6, 14, 3.4],
        "line-dasharray": [1.2, 1.8],
      },
    });
  }

  // ------------------------------------------------------------------
  // Map
  // ------------------------------------------------------------------
  const map = new maplibregl.Map({
    container: "map",
    style: earthStyle(),
    center: [-40, 28],
    zoom: isNarrow() ? 0.9 : 1.35,
    attributionControl: { compact: true },
    maxPitch: 70,
  });
  map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "bottom-right");
  const OVERLAY_PAD = () => (window.innerWidth >= 960
    ? { left: Math.min(620, window.innerWidth * 0.45), right: 0, top: 0, bottom: 0 }
    : isNarrow() ? { left: 0, right: 0, top: 40, bottom: Math.min(400, window.innerHeight * 0.5) } : { left: 0, right: 0, top: 0, bottom: 0 });
  map.setPadding(OVERLAY_PAD());
  map.on("style.load", addRoute);
  window.memmap = { map };
  if (state.mode === "map") setMode("map", false);

  async function setMode(mode, persist = true) {
    state.mode = mode;
    $("#mode-earth").classList.toggle("on", mode === "earth");
    $("#mode-map").classList.toggle("on", mode === "map");
    $("#mode-earth").setAttribute("aria-pressed", mode === "earth");
    $("#mode-map").setAttribute("aria-pressed", mode === "map");
    if (persist) store.set("memmap-mode", mode);
    map.setStyle(await styleFor(mode), { diff: false });
  }
  $("#mode-earth").onclick = () => state.mode !== "earth" && setMode("earth");
  $("#mode-map").onclick = () => state.mode !== "map" && setMode("map");

  // ------------------------------------------------------------------
  // Pins + screen-space clustering
  // ------------------------------------------------------------------
  const firstPhoto = (place) => {
    for (const p of place.people) if (p.photos.length) return p.photos[0].thumb;
    return null;
  };
  const initials = (name) => name.split(/\s+/).map((w) => w[0]).join("").slice(0, 2).toUpperCase();
  const avatar = (person, cls = "av") => {
    const ph = person.photos[0];
    return ph
      ? `<span class="${cls}" style="background-image:url('${ph.thumb}')"></span>`
      : `<span class="${cls}">${esc(initials(person.name))}</span>`;
  };

  const pins = PLACES.map((place, i) => {
    const el = document.createElement("div");
    el.className = "pin";
    el.setAttribute("role", "button");
    el.setAttribute("tabindex", "0");
    el.setAttribute("aria-label", `${place.name}: notes from ${place.people.map((p) => p.name).join(", ")}`);
    const photo = firstPhoto(place);
    el.innerHTML = `
      <div class="pin-body"><div class="pin-photo" ${photo ? `style="background-image:url('${photo}')"` : ""}>${photo ? "" : esc(initials(place.people[0].name))}</div></div>
      <span class="num" data-region="${place.region}">${place.num}</span>
      ${place.people.length > 1 ? `<span class="pin-count">${place.people.length}</span>` : ""}`;
    el.addEventListener("click", (e) => { e.stopPropagation(); openPlace(i, { fly: true }); });
    el.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openPlace(i, { fly: true }); } });
    if (canHover) {
      el.addEventListener("mouseenter", () => showHover(el, placeCard(place)));
      el.addEventListener("mouseleave", hideHover);
    }
    const marker = new maplibregl.Marker({ element: el, anchor: "bottom", opacityWhenCovered: "0" })
      .setLngLat([place.lng, place.lat]);
    return { el, marker, shown: false };
  });

  // Secondary pins (e.g. Gabby's Oberon).
  PLACES.forEach((place, i) => {
    if (!place.extra_pin) return;
    const el = document.createElement("div");
    el.className = "pin-extra";
    el.textContent = "✦";
    el.title = place.extra_pin.name;
    el.addEventListener("click", (e) => { e.stopPropagation(); openPlace(i, { fly: true }); });
    if (canHover) {
      el.addEventListener("mouseenter", () => showHover(el, `
        <p class="hc-names">${esc(place.people.map((p) => p.name).join(" & "))}'s next spot</p>
        <p class="hc-place">${esc(place.extra_pin.name)}</p>
        <p class="hc-cta">Open note →</p>`));
      el.addEventListener("mouseleave", hideHover);
    }
    const m = new maplibregl.Marker({ element: el, opacityWhenCovered: "0" }).setLngLat([place.extra_pin.lng, place.extra_pin.lat]);
    map.on("move", () => {
      const show = map.getZoom() >= 13 && isVisible(place.extra_pin.lng, place.extra_pin.lat, 100);
      if (show && !m._map) m.addTo(map);
      if (!show && m._map) m.remove();
    });
  });

  function centralAngle(a, b) {
    const R = Math.PI / 180;
    const dLat = (b.lat - a.lat) * R, dLng = (b.lng - a.lng) * R;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * R) * Math.cos(b.lat * R) * Math.sin(dLng / 2) ** 2;
    return 2 * Math.asin(Math.min(1, Math.sqrt(h))) / R;
  }

  // On the globe, map.project() folds far-side points onto the visible disk,
  // so check the horizon first, then the viewport.
  function isVisible(lng, lat, margin = 300) {
    if (centralAngle(map.getCenter(), { lng, lat }) > 78) return false;
    const pt = map.project([lng, lat]);
    const c = map.getContainer();
    return pt.x > -margin && pt.y > -margin && pt.x < c.clientWidth + margin && pt.y < c.clientHeight + margin;
  }

  let clusterMarkers = [];
  let lastSig = "";
  function recluster() {
    const items = PLACES.map((p, i) => ({
      i,
      pt: map.project([p.lng, p.lat]),
      front: isVisible(p.lng, p.lat),
      weight: p.people.length,
    }));
    const order = [...items].sort((a, b) => b.weight - a.weight || a.i - b.i);
    const taken = new Set();
    const groups = [];
    const hidden = [];
    for (const it of order) {
      if (taken.has(it.i)) continue;
      taken.add(it.i);
      if (!it.front) { hidden.push(it.i); continue; }
      const g = [it.i];
      for (const o of order) {
        if (taken.has(o.i) || !o.front) continue;
        if (Math.hypot(o.pt.x - it.pt.x, o.pt.y - it.pt.y) < CLUSTER_PX) { g.push(o.i); taken.add(o.i); }
      }
      groups.push(g.sort((a, b) => a - b));
    }
    const sig = groups.map((g) => g.join(",")).sort().join("|") + "/" + hidden.sort((a, b) => a - b).join(",");
    if (sig === lastSig) return;
    lastSig = sig;

    clusterMarkers.forEach((m) => m.remove());
    clusterMarkers = [];
    hidden.forEach((i) => { if (pins[i].shown) { pins[i].marker.remove(); pins[i].shown = false; } });
    for (const g of groups) {
      if (g.length === 1) {
        const pin = pins[g[0]];
        if (!pin.shown) { pin.marker.addTo(map); pin.shown = true; }
        continue;
      }
      g.forEach((i) => { if (pins[i].shown) { pins[i].marker.remove(); pins[i].shown = false; } });
      clusterMarkers.push(makeCluster(g));
    }
  }

  function clusterName(g) {
    const regions = new Set(g.map((i) => PLACES[i].region));
    const areas = new Set(g.map((i) => PLACES[i].area.split(",").pop().trim().replace(/^Tokyo$/, "Japan")));
    if (regions.size === 1 && regions.has("nyc")) return "New York City";
    if (areas.size === 1) return [...areas][0];
    if (regions.has("nyc")) return "New York & nearby";
    return "A few places";
  }

  function makeCluster(g) {
    const people = g.flatMap((i) => PLACES[i].people);
    const faces = people.filter((p) => p.photos.length).slice(0, 4);
    const el = document.createElement("div");
    el.className = "cluster";
    el.setAttribute("role", "button");
    el.setAttribute("tabindex", "0");
    el.innerHTML = `
      <div class="cluster-faces">${faces.map((p) => avatar(p)).join("")}</div>
      <div class="cluster-text"><b>${esc(clusterName(g))}</b><small>${g.length} places · ${people.length} notes</small></div>`;
    const lng = g.reduce((s, i) => s + PLACES[i].lng, 0) / g.length;
    const lat = g.reduce((s, i) => s + PLACES[i].lat, 0) / g.length;
    const zoomIn = () => {
      hideHover();
      stopSpin();
      const b = new maplibregl.LngLatBounds();
      g.forEach((i) => b.extend([PLACES[i].lng, PLACES[i].lat]));
      map.fitBounds(b, { padding: cameraPadding(110), maxZoom: 15, pitch: 30, duration: 2200, essential: true });
    };
    el.addEventListener("click", (e) => { e.stopPropagation(); zoomIn(); });
    el.addEventListener("keydown", (e) => { if (e.key === "Enter") zoomIn(); });
    if (canHover) {
      el.addEventListener("mouseenter", () => showHover(el, `
        <p class="hc-names" style="font-size:22px">${esc(clusterName(g))}</p>
        <p class="hc-area">${esc(people.map((p) => p.name).join(", "))}</p>
        <p class="hc-cta">Click to zoom in →</p>`));
      el.addEventListener("mouseleave", hideHover);
    }
    return new maplibregl.Marker({ element: el, anchor: "center", opacityWhenCovered: "0" }).setLngLat([lng, lat]).addTo(map);
  }

  let rafPending = false;
  map.on("move", () => {
    if (rafPending) return;
    rafPending = true;
    requestAnimationFrame(() => { rafPending = false; recluster(); });
  });
  map.on("load", recluster);
  // Re-sync mounted markers after long globe flights (MapLibre can leave stale transforms).
  map.on("moveend", () => {
    recluster();
    pins.forEach((p) => p.shown && p.marker.setLngLat(p.marker.getLngLat()));
    clusterMarkers.forEach((m) => m.setLngLat(m.getLngLat()));
  });

  // ------------------------------------------------------------------
  // Hover card
  // ------------------------------------------------------------------
  const hover = $("#hovercard");
  function placeCard(place) {
    const p0 = place.people[0];
    const ph = place.people.find((p) => p.photos.length)?.photos[0];
    const snippet = p0.message.join(" ");
    const short = snippet.length > 130 ? snippet.slice(0, 130).replace(/\s+\S*$/, "") + "…" : snippet;
    return `
      ${ph ? `<img src="${ph.web}" alt="">` : ""}
      <p class="hc-names">${esc(place.people.map((p) => p.name).join(", "))}</p>
      <p class="hc-place">${esc(place.name)}</p>
      <p class="hc-area">${esc(place.area)}</p>
      <p class="hc-snippet">“${esc(short)}”</p>
      <p class="hc-cta">${place.people.length > 1 ? `Open ${place.people.length} notes →` : "Open note →"}</p>`;
  }
  function showHover(anchorEl, html) {
    hover.innerHTML = html;
    hover.hidden = false;
    const r = anchorEl.getBoundingClientRect();
    const w = hover.offsetWidth, h = hover.offsetHeight;
    const rightEdge = window.innerWidth - (panel.classList.contains("open") ? panel.offsetWidth : 0) - 12;
    const leftEdge = (state.dirOpen ? $("#directory").offsetWidth : 0) + 12;
    let x = r.right + 14;
    if (x + w > rightEdge) x = r.left - w - 14;
    x = Math.max(leftEdge, Math.min(x, rightEdge - w));
    let y = r.top + r.height / 2 - h / 2;
    y = Math.max(70, Math.min(y, window.innerHeight - h - 12));
    hover.style.left = `${x}px`;
    hover.style.top = `${y}px`;
  }
  function hideHover() { hover.hidden = true; }
  map.on("movestart", hideHover);

  // ------------------------------------------------------------------
  // Camera
  // ------------------------------------------------------------------
  function cameraPadding(extra = 0) {
    if (isNarrow()) {
      const panel = $("#panel").classList.contains("open") ? window.innerHeight * 0.56 : 0;
      return { top: 80 + extra / 2, bottom: panel + (state.tour ? 80 : 0) + extra / 2, left: extra / 3, right: extra / 3 };
    }
    const panel = $("#panel").classList.contains("open") ? $("#panel").offsetWidth : 0;
    const dir = state.dirOpen ? $("#directory").offsetWidth : 0;
    return { top: 70 + extra, bottom: (state.tour ? 90 : 20) + extra, left: dir + extra, right: panel + extra };
  }

  function cameraFor(place, i) {
    const zoom = ZOOM[place.key] ?? (place.region === "nyc" ? 15.6 : 15.2);
    return {
      center: [place.lng, place.lat],
      zoom,
      pitch: zoom > 13 ? 55 : 35,
      bearing: ((i * 41) % 70) - 35,
    };
  }

  function flyToPlace(i) {
    const place = PLACES[i];
    const from = map.getCenter();
    const angle = centralAngle(from, place);
    // Explicit durations: MapLibre's maxDuration makes long flights jump instead of fly.
    const duration = angle > 2 ? Math.min(9000, 4200 + angle * 45) : angle > 0.05 ? 3200 : 1800;
    map.flyTo({
      ...cameraFor(place, i),
      padding: cameraPadding(),
      curve: angle > 2 ? 1.7 : 1.3,
      duration,
      essential: true,
    });
  }

  function flyHome() {
    closePanel();
    map.flyTo({ ...WORLD_VIEW, zoom: isNarrow() ? 0.9 : WORLD_VIEW.zoom, padding: { top: 0, bottom: 0, left: 0, right: 0 }, speed: 1, essential: true });
  }
  $("#brand").onclick = () => { stopTour(); flyHome(); };

  // Gentle spin while the intro is up.
  let spinLast = 0;
  function spin(t) {
    if (!state.spinning) return;
    if (spinLast) {
      const c = map.getCenter();
      map.setCenter([c.lng + (t - spinLast) * 0.004, c.lat]);
    }
    spinLast = t;
    requestAnimationFrame(spin);
  }
  function startSpin() { state.spinning = true; spinLast = 0; requestAnimationFrame(spin); }
  function stopSpin() { state.spinning = false; }
  ["mousedown", "touchstart", "wheel"].forEach((ev) => map.getCanvasContainer().addEventListener(ev, stopSpin, { passive: true }));

  // ------------------------------------------------------------------
  // Note panel
  // ------------------------------------------------------------------
  const panel = $("#panel");
  const panelScroll = $("#panel-scroll");

  function letterHTML(person) {
    const photos = person.photos;
    const photoBlock = photos.length
      ? `<div class="photos ${photos.length === 2 ? "two" : ""}">${photos.map((ph, k) => `
          <figure class="polaroid" data-full="${ph.web}" data-caption="${esc(ph.caption)}">
            <img src="${ph.web}" alt="${esc(person.name)} with Julia${ph.caption ? `: ${esc(ph.caption)}` : ""}" loading="lazy" width="${ph.w}" height="${ph.h}">
            ${ph.caption ? `<figcaption>${esc(ph.caption)}</figcaption>` : ""}
          </figure>`).join("")}</div>`
      : `<div class="no-photo">no photo, just the memory</div>`;
    return `
      <article class="letter" id="letter-${person.id}">
        <p class="letter-from">${esc(person.name)}</p>
        ${person.relation ? `<span class="letter-rel">${esc(person.relation)}</span>` : ""}
        ${photoBlock}
        <div class="letter-body">${person.message.map((p) => `<p>${esc(p)}</p>`).join("")}</div>
      </article>`;
  }

  function renderPanel(i) {
    const place = PLACES[i];
    const prev = PLACES[i - 1], next = PLACES[i + 1];
    panelScroll.innerHTML = `
      <div class="panel-head">
        <div class="panel-top">
          <span class="num" data-region="${place.region}">${place.num}</span>
          <span class="panel-kicker">Stop ${place.num} of ${PLACES.length} · ${REGION_LABEL[place.region]}</span>
          <span class="spacer"></span>
          <button class="icon-btn" id="panel-close" aria-label="Close notes">✕</button>
        </div>
        <h2>${esc(place.name)}</h2>
        <p class="area">${esc(place.area)}</p>
        ${place.full_name ? `<p class="fullname">${esc(place.full_name)}</p>` : ""}
        ${place.blurb ? `<p class="panel-blurb">${esc(place.blurb)}</p>` : ""}
        ${place.people.length > 1 ? `<div class="panel-people">${place.people.map((p) =>
          `<button class="person-chip" data-jump="${p.id}">${avatar(p)}${esc(p.name)}</button>`).join("")}</div>` : ""}
      </div>
      ${place.people.map(letterHTML).join("")}
      <div class="panel-foot">
        <button data-go="${i - 1}" ${prev ? "" : "disabled"}>← Previous stop<b>${prev ? esc(prev.name) : ""}</b></button>
        <button data-go="${i + 1}" ${next ? "" : "disabled"}>Next stop →<b>${next ? esc(next.name) : ""}</b></button>
      </div>`;
    panelScroll.scrollTop = 0;
    $("#panel-close").onclick = () => { stopTour(); closePanel(); };
  }

  panelScroll.addEventListener("click", (e) => {
    const jump = e.target.closest("[data-jump]");
    if (jump) {
      $(`#letter-${jump.dataset.jump}`)?.scrollIntoView({ behavior: "smooth", block: "start" });
      return;
    }
    const go = e.target.closest("[data-go]");
    if (go && !go.disabled) { openPlace(+go.dataset.go, { fly: true }); return; }
    const fig = e.target.closest(".polaroid");
    if (fig) openLightbox(fig.dataset.full, fig.dataset.caption);
  });

  function openPlace(i, { fly = false, person = null } = {}) {
    if (i < 0 || i >= PLACES.length) return;
    hideHover();
    stopSpin();
    hideIntro();
    if (isNarrow()) closeDirectory();
    if (state.current >= 0) pins[state.current].el.classList.remove("active");
    state.current = i;
    pins[i].el.classList.add("active");
    renderPanel(i);
    panel.classList.add("open");
    panel.setAttribute("aria-hidden", "false");
    document.body.classList.add("panel-open");
    if (person != null) {
      requestAnimationFrame(() => $(`#letter-${person}`)?.scrollIntoView({ block: "start" }));
    }
    document.querySelectorAll(".dir-place").forEach((r) => r.classList.toggle("active", +r.dataset.i === i));
    if (state.tour) updateTourbar();
    if (fly) flyToPlace(i);
    history.replaceState(null, "", `#stop=${PLACES[i].num}`);
  }

  function closePanel() {
    panel.classList.remove("open");
    panel.setAttribute("aria-hidden", "true");
    document.body.classList.remove("panel-open");
    if (state.current >= 0) pins[state.current].el.classList.remove("active");
    state.current = -1;
    document.querySelectorAll(".dir-place.active").forEach((r) => r.classList.remove("active"));
    history.replaceState(null, "", location.pathname + location.search);
  }

  // ------------------------------------------------------------------
  // Directory
  // ------------------------------------------------------------------
  const dir = $("#directory");
  $("#dir-count").textContent = `${PEOPLE_COUNT} friends · ${PLACES.length} places`;
  function renderDirectory(filter = "") {
    const q = filter.trim().toLowerCase();
    let html = "";
    for (const region of ["nyc", "northeast", "world"]) {
      const rows = PLACES.map((p, i) => ({ p, i })).filter(({ p }) => p.region === region).filter(({ p }) =>
        !q || [p.name, p.area, p.full_name, ...p.people.map((x) => x.name)].join(" ").toLowerCase().includes(q));
      if (!rows.length) continue;
      html += `<div class="dir-region">${REGION_LABEL[region]}</div>`;
      for (const { p, i } of rows) {
        html += `
          <div class="dir-place ${i === state.current ? "active" : ""}" data-i="${i}">
            <span class="num" data-region="${p.region}">${p.num}</span>
            <div><div class="dir-place-name">${esc(p.name)}</div><div class="dir-place-area">${esc(p.area)}</div></div>
            <div class="dir-people">${p.people.map((x) =>
              `<button class="person-chip" data-i="${i}" data-person="${x.id}">${avatar(x)}${esc(x.name)}</button>`).join("")}</div>
          </div>`;
      }
    }
    $("#dir-list").innerHTML = html || `<p class="muted" style="padding:16px">No one by that name… yet.</p>`;
  }
  renderDirectory();
  $("#dir-search").addEventListener("input", (e) => renderDirectory(e.target.value));
  $("#dir-list").addEventListener("click", (e) => {
    const chip = e.target.closest("[data-person]");
    const row = e.target.closest(".dir-place");
    if (!row) return;
    stopTour();
    openPlace(+row.dataset.i, { fly: true, person: chip ? +chip.dataset.person : null });
  });

  function openDirectory() {
    state.dirOpen = true;
    dir.classList.add("open");
    dir.setAttribute("aria-hidden", "false");
    hideIntro();
    stopSpin();
  }
  function closeDirectory() {
    state.dirOpen = false;
    dir.classList.remove("open");
    dir.setAttribute("aria-hidden", "true");
  }
  $("#btn-directory").onclick = () => (state.dirOpen ? closeDirectory() : openDirectory());
  document.querySelector('[data-close="directory"]').onclick = closeDirectory;

  // ------------------------------------------------------------------
  // Journey (guided tour)
  // ------------------------------------------------------------------
  const tourbar = $("#tourbar");
  $("#tour-track").innerHTML = PLACES.map(() => "<i></i>").join("");

  function updateTourbar() {
    const i = state.current;
    const place = PLACES[i];
    $("#tour-label").innerHTML = `${place.num}/${PLACES.length} · ${esc(place.people.map((p) => p.name).join(", "))} <span>at ${esc(place.name)}</span>`;
    [...$("#tour-track").children].forEach((el, k) => {
      el.className = k < i ? "done" : k === i ? "now" : "";
    });
    $("#tour-prev").disabled = i === 0;
    $("#tour-next").setAttribute("aria-label", i === PLACES.length - 1 ? "Finish" : "Next stop");
  }

  function startTour(at = 0) {
    state.tour = true;
    tourbar.hidden = false;
    closeDirectory();
    $("#finale").hidden = true;
    openPlace(at, { fly: true });
  }
  function stopTour() {
    state.tour = false;
    tourbar.hidden = true;
  }
  function tourNext() {
    if (state.current >= PLACES.length - 1) return showFinale();
    openPlace(state.current + 1, { fly: true });
  }
  function tourPrev() { if (state.current > 0) openPlace(state.current - 1, { fly: true }); }

  $("#tour-next").onclick = tourNext;
  $("#tour-prev").onclick = tourPrev;
  $("#tour-exit").onclick = () => stopTour();
  $("#btn-journey").onclick = () => startTour(state.current >= 0 ? state.current : 0);

  // ------------------------------------------------------------------
  // Intro + finale
  // ------------------------------------------------------------------
  const intro = $("#intro");
  $("#intro-lede").textContent = `${PLACES.length} places, ${PEOPLE_COUNT} people, one year`;

  function hideIntro() {
    if (intro.hidden || intro.classList.contains("leaving")) return;
    intro.classList.add("leaving");
    setTimeout(() => { intro.hidden = true; intro.classList.remove("leaving"); }, 650);
  }
  function burst() {
    if (!window.confetti || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const colors = ["#E4572E", "#F2B630", "#F4A6B8", "#FBF5EA", "#2D5D7B"];
    confetti({ particleCount: 120, spread: 80, origin: { y: 0.65 }, colors, zIndex: 70 });
    setTimeout(() => confetti({ particleCount: 70, angle: 60, spread: 60, origin: { x: 0, y: 0.7 }, colors, zIndex: 70 }), 250);
    setTimeout(() => confetti({ particleCount: 70, angle: 120, spread: 60, origin: { x: 1, y: 0.7 }, colors, zIndex: 70 }), 400);
  }

  $("#start-journey").onclick = () => { burst(); hideIntro(); startTour(0); };
  $("#start-roam").onclick = () => {
    hideIntro();
    stopSpin();
    map.flyTo({ center: [-73.985, 40.728], zoom: isNarrow() ? 11 : 11.6, pitch: 35, bearing: -18, padding: { top: 0, bottom: 0, left: 0, right: 0 }, speed: 0.8, curve: 1.5, essential: true });
  };

  const allNames = PLACES.flatMap((p) => p.people.map((x) => x.name));
  $("#finale-lede").textContent = `${PLACES.length} places, ${PEOPLE_COUNT} people, and every one of them loves you.`;
  $("#finale-names").textContent = allNames.join(" · ");

  function showFinale() {
    stopTour();
    closePanel();
    map.flyTo({ ...WORLD_VIEW, center: [-150, 38], zoom: isNarrow() ? 0.9 : 1.5, padding: OVERLAY_PAD(), speed: 0.8, essential: true });
    const fin = $("#finale");
    fin.hidden = false;
    burst();
  }
  $("#finale-roam").onclick = () => { $("#finale").hidden = true; map.easeTo({ padding: { top: 0, bottom: 0, left: 0, right: 0 }, duration: 800 }); };
  $("#finale-again").onclick = () => { $("#finale").hidden = true; burst(); startTour(0); };

  // ------------------------------------------------------------------
  // Lightbox
  // ------------------------------------------------------------------
  const lb = $("#lightbox");
  function openLightbox(src, caption) {
    $("img", lb).src = src;
    $("figcaption", lb).textContent = caption || "";
    lb.hidden = false;
  }
  lb.onclick = () => { lb.hidden = true; };

  // ------------------------------------------------------------------
  // Keyboard + deep links
  // ------------------------------------------------------------------
  document.addEventListener("keydown", (e) => {
    if (e.target.matches("input, textarea")) return;
    if (e.key === "Escape") {
      if (!lb.hidden) lb.hidden = true;
      else if (state.dirOpen) closeDirectory();
      else if (state.current >= 0) { stopTour(); closePanel(); }
    }
    if (state.tour && e.key === "ArrowRight") tourNext();
    if (state.tour && e.key === "ArrowLeft") tourPrev();
  });

  const hash = new URLSearchParams(location.hash.slice(1));
  const deepStop = PLACES.findIndex((p) => String(p.num) === hash.get("stop"));
  if (hash.get("mode") === "map" || hash.get("mode") === "earth") setMode(hash.get("mode"), false);
  if (deepStop >= 0) {
    intro.hidden = true;
    map.once("load", () => {
      if (hash.has("tour")) startTour(deepStop);
      else openPlace(deepStop, { fly: true });
    });
  } else if (hash.has("roam")) {
    intro.hidden = true;
    map.setPadding({ top: 0, bottom: 0, left: 0, right: 0 });
  } else {
    map.once("load", startSpin);
  }
})();
